WHEN MATCHED THEN UPDATE SET TOBCAT='Phrasing Playground (S23)', TOBDESC=q'[<div><i class="bbs-keywords">What is it : </i>Designer sandbox for <code>POST /api/ai/engine/diagnose</code> - shows skill scores, vocabulary hits, lexical pipeline, bind feasibility, and dampened INTENT_PHRASEs <em>without</em> running SQL or writing to the DB.</div><div><i class="bbs-keywords">Workflow : </i><li>Enter natural-language question + retailer.</li><li>Inspect top skills and why the router won or lost.</li><li>Adjust vocabulary in Skill Builder based on results.</li></div>]', TOBDESC2=q'[<div><i class="bbs-keywords">When to use : </i>Debugging misroutes (e.g. item vs vendor skills) before changing production vocabulary packs.</div>]', TOBDMAJ=SYSDATE, TOBUTIL='admin'
WHEN NOT MATCHED THEN INSERT (TOBID,TOBCAT,TOBDESC,TOBDESC2,TOBLANGUE,TOBDCRE,TOBDMAJ,TOBUTIL) VALUES ('SCR0000000059','Phrasing Playground (S23)',q'[<div><i class="bbs-keywords">What is it : </i>Designer sandbox for <code>POST /api/ai/engine/diagnose</code> - shows skill scores, vocabulary hits, lexical pipeline, bind feasibility, and dampened INTENT_PHRASEs <em>without</em> running SQL or writing to the DB.</div><div><i class="bbs-keywords">Workflow : </i><li>Enter natural-language question + retailer.</li><li>Inspect top skills and why the router won or lost.</li><li>Adjust vocabulary in Skill Builder based on results.</li></div>]',q'[<div><i class="bbs-keywords">When to use : </i>Debugging misroutes (e.g. item vs vendor skills) before changing production vocabulary packs.</div>]','us_US',SYSDATE,SYSDATE,'admin');

