WHEN MATCHED THEN UPDATE SET TOBCAT='Supply Chain Assistant (S14)', TOBDESC=q'[<div><i class="bbs-keywords">What is it : </i>Analyst <b>natural-language</b> interface: routes the question to a skill, resolves binds (vendor, store, item), runs GOLD SQL templates, and returns a summarized answer with optional result tables.</div><div><i class="bbs-keywords">Workflow : </i><li>Ask in plain language -> review confidence and clarification chips if low.</li><li>Execute -> human summary + evidence + export.</li><li>Thumbs feedback feeds the phrasing curation queue.</li></div>]', TOBDESC2=q'[<div><i class="bbs-keywords">Tips : </i><li>Item card follow-ups (add retail, EAN) work on the same LU after an item header result.</li><li>Admins see engine diagnostics; analysts see chat + inline results only.</li></div>]', TOBDMAJ=SYSDATE, TOBUTIL='admin'
