WHEN MATCHED THEN UPDATE SET TOBCAT='AI Data Health (S24)', TOBDESC=q'[<div><i class="bbs-keywords">What is it : </i>Operational <b>data pipeline monitor</b> - card grid of checks (item, ranging, orders, receipts, stock, sales) with severity, trend, and last-run status from <code>AI_DATA_CHECK_RESULT</code>.</div><div><i class="bbs-keywords">Workflow : </i><li>Filter by retailer and schedule tier (realtime / hourly / nightly).</li><li><b>Run now</b> triggers <code>AI_RUN_DATA_CHECKS</code> for a tier.</li><li><b>History</b> -> drill-down rows; <b>Investigate</b> opens Assistant with context.</li></div>]', TOBDESC2=q'[<div><i class="bbs-keywords">When to use : </i>Morning operational review before replenishment/blocker analysis - catches silent feed failures (POS, receipts) and master-data gaps.</div>]', TOBDMAJ=SYSDATE, TOBUTIL='admin'
WHEN NOT MATCHED THEN INSERT (TOBID,TOBCAT,TOBDESC,TOBDESC2,TOBLANGUE,TOBDCRE,TOBDMAJ,TOBUTIL) VALUES ('SCR0000000061','AI Data Health (S24)',q'[<div><i class="bbs-keywords">What is it : </i>Operational <b>data pipeline monitor</b> - card grid of checks (item, ranging, orders, receipts, stock, sales) with severity, trend, and last-run status from <code>AI_DATA_CHECK_RESULT</code>.</div><div><i class="bbs-keywords">Workflow : </i><li>Filter by retailer and schedule tier (realtime / hourly / nightly).</li><li><b>Run now</b> triggers <code>AI_RUN_DATA_CHECKS</code> for a tier.</li><li><b>History</b> -> drill-down rows; <b>Investigate</b> opens Assistant with context.</li></div>]',q'[<div><i class="bbs-keywords">When to use : </i>Morning operational review before replenishment/blocker analysis - catches silent feed failures (POS, receipts) and master-data gaps.</div>]','us_US',SYSDATE,SYSDATE,'admin');

