WHEN MATCHED THEN UPDATE SET TOBCAT='Alerts journal', TOBDESC=q'[<div><i class="bbs-keywords">What is it : </i>Run history for ICR <b>scheduled and on-demand alerts</b>. Each row in <code>ALERTLOG</code> is one execution: alert id, request id, status, phase, duration, row count, and error text.</div><div><i class="bbs-keywords">Views : </i><li><b>Live</b> - recent runs with auto-refresh.</li><li><b>Weekly / Monthly</b> - duration trends and execution volume charts.</li><li><b>Detail</b> - full log fields for a selected run.</li></div>]', TOBDESC2=q'[<div><i class="bbs-keywords">When to use : </i>Troubleshooting failed or timeout alerts, confirming a cron job fired (pair with <b>Critical Alert Watchdog</b>), or reviewing row counts before changing alert SQL on Alerts management.</div>]', TOBDMAJ=SYSDATE, TOBUTIL='admin'
WHEN NOT MATCHED THEN INSERT (TOBID,TOBCAT,TOBDESC,TOBDESC2,TOBLANGUE,TOBDCRE,TOBDMAJ,TOBUTIL) VALUES ('SCR0000000063','Alerts journal',q'[<div><i class="bbs-keywords">What is it : </i>Run history for ICR <b>scheduled and on-demand alerts</b>. Each row in <code>ALERTLOG</code> is one execution: alert id, request id, status, phase, duration, row count, and error text.</div><div><i class="bbs-keywords">Views : </i><li><b>Live</b> - recent runs with auto-refresh.</li><li><b>Weekly / Monthly</b> - duration trends and execution volume charts.</li><li><b>Detail</b> - full log fields for a selected run.</li></div>]',q'[<div><i class="bbs-keywords">When to use : </i>Troubleshooting failed or timeout alerts, confirming a cron job fired (pair with <b>Critical Alert Watchdog</b>), or reviewing row counts before changing alert SQL on Alerts management.</div>]','us_US',SYSDATE,SYSDATE,'admin');

